export const ROLE_NAMES={literature_reader:'文献审阅',code_inspector:'代码检查',planner:'计划编排',experiment_runner:'实验执行',cross_auditor:'交叉核查',reporter:'报告整理'};
const kinds={plan_scheduled:'按计划排程',stage_started:'开始阶段执行',stage_finished:'阶段执行结束',stage_checked:'核对阶段输出',execution_checked:'汇总执行证据',report_written:'写入执行报告',stopped:'结束排程'};
export function activityEvents(report){
 const execution=report?.execution,rows=execution?.events||[];
 return [...(report?.activity||[]),...rows.map((x,index)=>({...x,roles:[x.role],status:x.kind==='stage_started'&&execution.status==='running'&&!rows.slice(index+1).some(y=>y.kind==='stage_finished'&&y.stage===x.stage)?'running':x.kind==='stage_finished'&&x.exit_code!==0?'failed':'completed',title:kinds[x.kind]||x.kind,detail:report.review?.plan?.stages?.find(s=>s.id===x.stage)?.title||x.reason||({completed:'已结束',running:'执行中',failed:'执行受阻',cancelled:'已停止',expired:'已超时'}[x.status]||x.status)||''}))];
}
export function activityGroups(report){
 const groups=new Map();for(const event of activityEvents(report)){let key='review',title='材料审阅与计划';if(event.stage){key='stage:'+event.stage;title=report.review?.plan?.stages?.find(s=>s.id===event.stage)?.title||event.stage;}else if(event.kind){key=['stopped','execution_checked','report_written'].includes(event.kind)?'execution-result':'execution-setup';title=key==='execution-result'?'实验核查与汇总':'执行准备';}if(!groups.has(key))groups.set(key,{key,title,events:[]});groups.get(key).events.push(event);}return [...groups.values()];
}
export function activityView(report,esc,{open=true}={}){
 const events=activityEvents(report);if(!events.length)return '';
 const active=events.filter(x=>x.status==='running'),last=active.at(-1)||events.at(-1),roles=Object.entries(ROLE_NAMES),running=report.status==='reviewing'||['running','starting','queued','cancelling'].includes(report.execution?.status);
 return `<section class="review-activity" aria-label="审查协作进度"><header><div><h2>${running?'正在协作审查':'审查协作记录'}</h2><p role="status" aria-live="polite">${esc(last.title)}${last.detail?' · '+esc(last.detail):''}</p></div><span>${running?'<span class="online-spinner" aria-hidden="true"></span>':'过程已记录'}</span></header><div class="review-role-lanes">${roles.map(([id,label])=>{const rows=events.filter(x=>(x.roles||[]).includes(id)),running=rows.some(x=>x.status==='running'),failed=rows.some(x=>x.status==='failed'),done=rows.some(x=>x.status==='completed'),state=running?'running':failed?'failed':done?'completed':'idle';return `<div class="review-role-lane ${state}"><span class="review-role-dot" aria-hidden="true">${state==='completed'?'✓':state==='failed'?'!':''}</span><strong>${label}</strong><small>${running?'进行中':failed?'需关注':done?'已执行':rows.some(x=>x.status==='skipped')?'本次跳过':report.status==='reviewing'?'等待任务':'未执行'}</small></div>`;}).join('')}</div><details class="review-activity-log" ${open?'open':''}><summary>查看 ${events.length} 条活动记录</summary><div class="activity-groups">${activityGroups(report).map(group=>`<section class="activity-group"><h3>${esc(group.title)}<span>${group.events.length} 条记录</span></h3><ol>${group.events.map(x=>`<li class="activity-event ${esc(x.status)}"><time>${x.time?esc(new Date(x.time*1000).toLocaleTimeString('zh-CN',{hour12:false})):''}</time><div><header><strong>${esc(x.title)}</strong><span>${esc({running:'进行中',completed:'已结束',skipped:'已跳过',failed:'未完成'}[x.status]||x.status)}</span></header><small>${(x.roles||[]).map(id=>esc(ROLE_NAMES[id]||id)).join(' / ')}</small>${x.detail?`<p>${esc(x.detail)}</p>`:''}</div></li>`).join('')}</ol></section>`).join('')}</div></details><p class="online-footnote">文献、代码和规划职责共享主审请求；交叉复核按适用条件单独调用，实验事件来自实际执行。</p></section>`;
}
